          "qt": "65 歳の女性。多発関節痛を主訴に来院した。5 か月前に自宅近くの医療機関で関節リウマチの診断を受けた。B 型 およびC 型肝炎ウイルス検査、結核菌特異的全血インターフェロンγ遊離測定法〈IGRA〉は陰性で、メトトレキサート とプレドニゾロンによる治療が開始されたが、症状が改善しないため紹介受診となった。多発関節炎を認め、生物学 的製剤による治療の適応と考えられた。併存疾患はない。輸血歴、結核の家族歴や接触歴もない。末梢血白血球数、 リンパ球数、血清IgG、胸部エックス線検査に異常を認めない。 この患者で生物学的製剤による治療開始前に追加すべき検査はどれか。",
